<span class="line">  routerLog<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">&#39;Redirecting to login page&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
